+/**
+ * Variance per item between two days (inclusive, UTC): theoretical use from
+ * sales, actual use from "consume" movements, difference = actual - theoretical.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (instant) => {
+    const day = dayOf(instant);
+    return day >= from && day <= to;
+  };
+  const round = (n) => Math.round(n * 1000) / 1000;
+  const theoretical = new Map();
+  for (const sale of store.data.sales ?? []) {
+    if (!inRange(sale.soldAt)) continue;
+    for (const u of sale.uses) theoretical.set(u.itemId, (theoretical.get(u.itemId) ?? 0) + u.qty);
+  }
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const itemId = batchItem.get(m.batchId);
+    actual.set(itemId, (actual.get(itemId) ?? 0) + m.qty);
+  }
+  return listItems(store)
+    .map((item) => {
+      const t = round(theoretical.get(item.id) ?? 0);
+      const a = round(actual.get(item.id) ?? 0);
+      return { itemId: item.id, name: item.name, unit: item.unit, theoretical: t, actual: a, difference: round(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
