+// Sales from the till: each dish sold uses one portion of its recipe per qty.
+// A sale keeps the quantities it used, so later recipe changes do not rewrite
+// what was theoretically used.
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** Tickets that have been imported already. */
+export function importedTickets(store) {
+  return new Set((store.data.sales ?? []).map((s) => s.ticket));
+}
+
+/** Records one sold dish and consumes its ingredients at `soldAt`, with the ref sale:<ticket>. */
+export function recordSale(store, { ticket, soldAt, dishId, qty }) {
+  const recipe = getRecipe(store, getDish(store, dishId).recipeId);
+  const uses = scaled(recipe, qty).filter((n) => n.qty > 0);
+  for (const n of uses) consume(store, n.itemId, n.qty, { at: soldAt, ref: `sale:${ticket}` });
+  store.data.sales ??= [];
+  const sale = { id: store.nextId("sale"), ticket, soldAt, dishId, qty, uses };
+  store.data.sales.push(sale);
+  return sale;
+}
